import test from 'node:test';
import assert from 'node:assert/strict';
import {hostWidths,deviceCases,escapeLayers} from './fixtures/ask-pane-host.mjs';
import {askPaneLayout,paneTransition,initialPaneState,topEscapeLayer,tabKey,arrivalSelection} from '../components/panel/askPaneLayout.ts';
import {createBrowserLeave} from '../lib/browser/pane-host.mjs';
const ref={kind:'browser',id:'task'};
for(const row of hostWidths)test(`Browser H5 width ${row.width}`,()=>{const l=askPaneLayout({width:row.width,height:900,mode:'popout',selected:true});assert.equal(l.split,row.split);for(const k of ['chat','gutter','pane'])assert.ok(Math.abs(l[k]-row[k])<.001);});
for(const row of deviceCases)test('Browser H5 '+row.name,()=>{const l=askPaneLayout({...row,selected:true,safeArea:80});assert.equal(l.landscape,row.landscape);assert.equal(l.compact,row.compact);if(row.stage)assert.equal(l.stage,row.stage);if(row.landscape){assert.equal(l.actionColumn,128);assert.ok(l.stage>=200);}});
test('Browser shares one history entry across Chat/Canvas switches and rotation',()=>{let s=paneTransition(initialPaneState('user:thread'),{type:'select',ref,mode:'sheet'});assert.equal(s.history,'push');s=paneTransition(s,{type:'select',ref:{kind:'canvas',id:'canvas'},mode:'sheet'});assert.equal(s.history,'replace');s=paneTransition(s,{type:'select',ref,mode:'sheet'});assert.equal(s.history,'replace');s=paneTransition(s,{type:'rotate'});assert.equal(s.history,'none');s=paneTransition(s,{type:'exit'});assert.equal(s.history,'back');assert.equal(paneTransition(s,{type:'exit'}).history,'replace');});
test('failed Browser leave retains selection/history; one confirmed exit',async()=>{let allowed=false,calls=0;const messages=[];const leave=createBrowserLeave({releaseAndPause:async()=>{calls++;return allowed;},transition:paneTransition,announce:x=>messages.push(x)});const s=paneTransition(initialPaneState('user:thread'),{type:'select',ref,mode:'sheet'});assert.equal(await leave(s,{type:'exit'},{control:'person'}),s);assert.equal(calls,0);assert.equal(await leave(s,{type:'exit'},{control:'person',confirmed:true}),s);allowed=true;const out=await leave(s,{type:'exit'},{control:'person',confirmed:true});assert.equal(out.history,'back');assert.equal(out.selected,null);assert.equal(messages.length,2);});
test('leave exceptions and concurrent clicks cannot double exit',async()=>{let resolve;const leave=createBrowserLeave({releaseAndPause:()=>new Promise(r=>resolve=r),transition:paneTransition,announce:()=>{}});const s=paneTransition(initialPaneState('s'),{type:'select',ref,mode:'sheet'});const first=leave(s,{type:'exit'});assert.equal(await leave(s,{type:'exit'}),s);resolve(true);assert.equal((await first).history,'back');const bad=createBrowserLeave({releaseAndPause:async()=>{throw Error('private');},transition:paneTransition,announce:()=>{}});assert.equal(await bad(s,{type:'exit'}),s);});
test('passive Watch exit leaves staff running; content switches retain attendance',async()=>{let calls=0;const leave=createBrowserLeave({releaseAndPause:async()=>{calls++;return true;},transition:paneTransition,announce:()=>{}});const s=paneTransition(initialPaneState('joe:local'),{type:'select',ref,mode:'sheet'});assert.equal((await leave(s,{type:'exit'},{passiveWatch:true})).history,'back');await leave(s,{type:'select',ref:{kind:'canvas',id:'c'},mode:'sheet'});assert.equal(calls,0);});
test('H5 keyboard tabs and escape priorities use shared vocabulary',()=>{assert.equal(tabKey(['chat','canvas','browser'],'canvas','ArrowDown',true),'browser');assert.equal(topEscapeLayer(Object.entries(escapeLayers).map(([id,priority])=>({id,priority}))).id,'menu');});
test('Browser attention preserves chosen Canvas; Canvas never steals takeover',()=>{const canvas={kind:'canvas',id:'c'};assert.deepEqual(arrivalSelection({selected:canvas,expanded:true,humanChoice:true,canFollow:true,arrivals:[{...ref,takeover:true,attention:'needs_you'}]}),canvas);assert.deepEqual(arrivalSelection({selected:ref,expanded:true,canFollow:true,arrivals:[{kind:'canvas',id:'c',attention:'new'}]}),ref);});
test('Browser state does not cross person/thread or restore without auth',()=>{let s=paneTransition(initialPaneState('a:t'),{type:'select',ref,mode:'sheet'});s=paneTransition(s,{type:'close-operator'});assert.equal(paneTransition(s,{type:'reopen',authorized:false,mode:'sheet'}).selected,null);assert.equal(paneTransition(s,{type:'scope',scope:'b:t'}).remembered,null);});

// Expectations written before the Phase 1 renderer, device helper and API adapter.
const {browserRenderHarness,browserLandscapeRows}=await import('./fixtures/ask-pane-host.mjs');
const render=await browserRenderHarness();
const {BrowserView}=await import('../components/panel/BrowserView.tsx');
const {classifyBrowserDevice,stableBrowserDevice}=await import('../components/panel/browser/device.ts');
const {browserModel,afterBrowserControl,letterboxPoint}=await import('../components/panel/browser/model.ts');
const base={canChooseProject:true,state:'working',origin:'city.example',phone:false,ownerName:'Joe',personName:'Abigail',width:360};
const view=(p={})=>render(BrowserView,{model:{...base,...p},slot:'all',onAction(){}});
test('C01 real pane renders 360, 820, 1280 with contained image and state accessible name',()=>{for(const width of [360,820,1280]){const html=view({width,frameUrl:'data:image/jpeg;base64,/9j/'});assert.match(html,/object-contain/);assert.match(html,/Live view of city.example. Agent is working./);assert.match(html,/Stop browser/);assert.match(html,/Zoom/);assert.match(html,/Pause live view/);}});
test('C02 phone replaces every takeover variant with exact instruction',()=>{for(const state of ['working','paused_private','other_device','write_blocked']){const html=view({state,phone:true,frameUrl:'frame'});assert.doesNotMatch(html,/>Take over(?: again| here)?</);if(state!=='write_blocked')assert.match(html,/Take over on a tablet or computer. Open SJC OS on your iPad or computer, then Operator › Browser./);}});
test('C03 device classification uses screen 599/600, native, mini and Split View',()=>{for(const [w,h,native,phone] of [[599,1200,false,true],[600,960,false,false],[820,1180,false,false],[744,1133,false,false],[820,1180,true,true],[360,800,true,true]])assert.equal(classifyBrowserDevice({width:w,height:h,native}),phone?'phone':'tablet-computer');});
test('C04 rotation, keyboard and pane resize never reclassify loaded device',()=>{const device=stableBrowserDevice({width:820,height:1180,native:false});for(const viewport of [[360,700],[800,360],[820,490]])assert.equal(device(...viewport),'tablet-computer');assert.equal(stableBrowserDevice({width:360,height:800,native:false})(800,360),'phone');});
test('C05 tablet narrow pane retains takeover while identical rotated phone does not',()=>{assert.match(view({width:360,phone:false}),/>Take over</);assert.doesNotMatch(view({width:800,phone:true}),/>Take over</);});
test('C06 exact privacy confirmation and fresh explanation render',()=>{assert.match(view({dialog:'takeover'}),/Take over\? After you take over, the agent can't see this page anymore. To let it keep reading, open a fresh browser afterwards./);assert.match(view({dialog:'fresh'}),/Starts a new browser for this task on the same sites. Pages you signed in to will need signing in again./);});
test('C07 Done then Keep paused persists private rest without Continue or no-op Keep paused',()=>{const first=afterBrowserControl({...base,state:'controlling'},'done');assert.equal(first.state,'done');const rest=afterBrowserControl(first,'keep_paused');assert.equal(rest.state,'paused_private');const html=view(rest);assert.match(html,/Paused. The agent can't read this page./);assert.match(html,/Take over again/);assert.match(html,/Open a fresh browser/);assert.doesNotMatch(html,/>Continue<|>Keep paused</);});
test('C08 final-blocked card has Close only and never a submit action',()=>{const html=view({state:'final_blocked'});assert.match(html,/This version stops here. Nothing was submitted./);assert.equal((html.match(/<button/g)||[]).length,1);assert.match(html,/>Close</);});
test('C09 write-blocked desktop and phone are honest and never send',()=>{assert.match(view({state:'write_blocked'}),/This version can only read pages. This button sends information to the site./);assert.match(view({state:'write_blocked',phone:true}),/This version reads public pages only. Sending information isn't available yet./);assert.doesNotMatch(view({state:'write_blocked'}),/>Submit|>Send once/);});
test('C10 queue/offer/full/expiry exact copy and explicit actions',()=>{for(const [state,copy] of [['queued',"Browser is busy. You're number 2 in line."],['queue_full','Browser is busy and the line is full. Try again in a few minutes.'],['queue_expired','You left the line after 5 minutes.'],['offer','Browser is ready. Open within 30 seconds.'],['offer_expired','You missed your turn.']])assert.ok(view({state,queuePosition:2}).includes(copy));assert.doesNotMatch(view({state:'queued',inUse:[{person_label:'Mark',project_label:'Secret'}]}),/Mark|Secret/);});
test('C11 public page and files are actual decisions with explicit refusal',()=>{assert.match(view({state:'read_review',readUrls:['https://city.example/public']}),/Read this page\?/);assert.match(view({state:'read_review'}),/>Read once</);assert.match(view({state:'read_review'}),/>Don't open</);assert.match(view({state:'resource_review'}),/This page needs these files/);assert.match(view({state:'resource_review'}),/>Keep blocked</);});
test('C12 Sites keeps exact addresses distinct from origins and limits resource decisions',()=>{const html=view({dialog:'sites',sites:['https://city.example'],readUrls:['https://city.example/public?a=1']});for(const copy of ['This task can use these sites.','Pages this task may read','Review page addresses',"This version reads public pages only. Sending job details isn't available yet.",'https://city.example/public?a=1'])assert.ok(html.includes(copy));assert.match(view({state:'resource_review',readUrls:Array(21).fill('https://city.example/a')}),/disabled/);});
test('C13 idle last minute warning, crash, latch, expiry blank image',()=>{assert.match(view({idleSeconds:60}),/Browser closes in 60 seconds./);for(const state of ['crashed','latched','auth_expired','access_removed','idle_closed'])assert.doesNotMatch(view({state,frameUrl:'data:image/jpeg;base64,secret'}),/<img/);assert.match(view({state:'latched'}),/Browser stopped because the server is busy. Your saved files are safe./);});
test('C14 local pause has exact warning and never implies agent paused',()=>{const html=view({livePaused:true});assert.match(html,/Live view paused. The agent may still be working./);assert.match(html,/Resume live view/);});
test('C15 captured keys explain Escape, local controls stay keyboard accessible',()=>{const html=view({state:'controlling',capture:true});assert.match(html,/Keys go to the website · Esc to stop/);assert.match(html,/tabindex="0"/);assert.match(html,/Done/);assert.doesNotMatch(html,/clipboard/i);});
test('C16 letterbox mapping rejects padding and maps canonical viewport',()=>{assert.equal(letterboxPoint({left:0,top:0,width:400,height:400},200,10),null);assert.deepEqual(letterboxPoint({left:0,top:0,width:400,height:400},200,200),{x:640,y:400});});
test('C17 stale private snapshots never grant controls without local token',()=>{assert.equal(browserModel({task:{private:true,control:'person',state:'active'},hasControl:false}).state,'other_device');});
test('C18 leave confirm and failed pause retain explanatory recovery',()=>{assert.match(view({dialog:'leave'}),/Pause browser and return to Chat\?/);assert.match(view({state:'pause_failed'}),/Couldn't pause the browser. Keep this screen open, or stop the browser./);assert.match(view({state:'pause_failed'}),/Try again/);});
test('C19 landscape Browser fixtures keep one shared 48/20 center and >=200 stage',()=>{for(const row of browserLandscapeRows){assert.equal(row.stage,row.height-row.title-row.meta-row.padding-row.safeArea);assert.ok(row.stage>=200);assert.equal(row.right,128);assert.equal(row.strip,row.name.startsWith('owner')?0:64);}});
test('C20 status changes have one polite region; frame is never live',()=>{const html=view({frameUrl:'data:image/jpeg;base64,/9j/'});assert.equal((html.match(/aria-live="polite"/g)||[]).length,1);assert.doesNotMatch(html,/<img[^>]*aria-live/);assert.match(html,/motion-reduce/);});
test('C30 real API adapter binds cookie/CSRF/viewer headers, parses frames and never puts secrets in URLs',async()=>{
 const {browserAPI}=await import('../components/panel/browser/api.ts');const old=globalThis.fetch,calls=[];const id='10000000-0000-4000-8000-000000000001';
 const v={viewer_id:id,device_secret:'d'.repeat(43)};
 globalThis.fetch=async(url,options)=>{calls.push({url,options});if(url.endsWith('/csrf'))return Response.json({ok:true,csrf_token:'csrf',expires_at:'2099-01-01T00:00:00Z'});if(url.endsWith('/events'))return new Response(new TextEncoder().encode('event: file\ndata: {"available":false}\n\n'),{headers:{'Content-Type':'text/event-stream'}});return Response.json({ok:true,left:true});};
 try{await browserAPI.leave(id,v);const seen=[];await browserAPI.events(id,v,new AbortController().signal,(...e)=>seen.push(e));assert.equal(calls[1].options.headers['X-SJC-CSRF'],'csrf');assert.equal(calls[1].options.headers['X-SJC-Browser-Device'],v.device_secret);assert.ok(calls.every(c=>c.options.credentials==='same-origin'&&!c.url.includes(v.device_secret)));assert.deepEqual(seen,[['file',{available:false}]]);}finally{globalThis.fetch=old;}
});

// C2 expectations precede adapter/session integration. These exercise the same
// pure projection/fence helpers called by the hook, plus real fetch and markup.
const sessionTools=()=>import('../components/panel/browser/session.ts');
const apiTools=()=>import('../components/panel/browser/api.ts');
const errorCopies={
 DISABLED:"Browser isn't available yet.",ATTENDED_ONLY:'You left the browser. The agent paused.',NOT_AUTHENTICATED:'Sign in again to continue.',NOT_FOUND:'Browser closed.',FORBIDDEN:'Your access changed. Browser stopped.',REVOKED:'Your access changed. Browser stopped.',BUSY:'Browser is busy and the line is full. Try again in a few minutes.',RESOURCE_LIMIT:'Browser stopped because the server is busy. Your saved files are safe.',SERVICE_UNAVAILABLE:"Couldn't connect to the browser.",CAPABILITY_EXPIRED:'Sign in again to continue.',BAD_INPUT:"This address can't be opened in the browser.",IDEMPOTENCY_CONFLICT:'Connected. Review the page before continuing.',SITE_BLOCKED:"This site isn't allowed for this task: city.example.",ADDRESS_BLOCKED:"This address can't be opened in the browser.",REVIEW_REQUIRED:'Read this page?',CONTROL_HELD:"You're in control on your other device.",OBSERVATION_STALE:'Connected. Review the page before continuing.',PRIVATE_INPUT_REQUIRED:"Private — login or account details. The agent can't see this page.",ADAPTER_REQUIRED:'This site needs you for the next step.',LOGIN_NOT_AVAILABLE:'No saved login for this site.',LOGIN_ORIGIN_MISMATCH:"This page doesn't match the saved login's site.",LOGIN_FIELDS_CHANGED:"This page doesn't match the saved login's site.",VAULT_UNAVAILABLE:'Saved logins are unavailable. You can sign in yourself.',REVIEW_UNAVAILABLE:'Preparing your review. Nothing has been submitted.',AMOUNT_UNKNOWN:'Preparing your review. Nothing has been submitted.',PROJECT_FILE_REQUIRED:'This file type isn\'t supported.',FILE_FORBIDDEN:'Your access changed. Browser stopped.',FILE_CHANGED:"This file couldn't be made safe. It wasn't saved.",FILE_TOO_LARGE:'File is too large. Maximum 25 MB.',PHASE1_READ_ONLY:'This version can only read pages. This button sends information to the site.',REVIEW_PENDING:'The page is locked while this review is open.',REVIEW_STALE:'The page changed. Review the new version before submitting.',STREAM_STALE:'Connection lost. Browser paused.',CONTROL_EXPIRED:'Browser is paused.',QUEUE_FULL:'Browser is busy and the line is full. Try again in a few minutes.',OFFER_EXPIRED:'You missed your turn.',READ_EXPIRED:'Read this page?',READ_PROVENANCE_UNKNOWN:'Read this page?',FRAME_TOO_LARGE:'Connection lost. Browser paused.',RATE_LIMIT:"Couldn't connect to the browser.",AUTH_EXPIRED:'Sign in again to continue.',LATCHED:'Browser stopped because the server is busy. Your saved files are safe.'};
for(const [code,copy] of Object.entries(errorCopies))test(`C2 exact error copy BROWSER_${code}`,async()=>{const {browserErrorCopy}=await import('../components/panel/browser/model.ts');assert.equal(browserErrorCopy('BROWSER_'+code,{origin:'city.example'}),copy);});
test('C2 error table covers every frozen BrowserError code',async()=>{const {ERROR_CODES}=await import('../lib/browser/phase1-contracts.mjs');assert.deepEqual(Object.keys(errorCopies).map(c=>'BROWSER_'+c).sort(),[...ERROR_CODES].sort());});
test('C2 phone write refusal and unknown error are safe exact copy',async()=>{const {browserErrorCopy}=await import('../components/panel/browser/model.ts');assert.equal(browserErrorCopy('BROWSER_PHASE1_READ_ONLY',{phone:true}),"This version reads public pages only. Sending information isn't available yet.");assert.equal(browserErrorCopy('untrusted page error'),"Couldn't connect to the browser.");});
test('C2 absent queue position never invents second place',()=>{assert.doesNotMatch(view({state:'queued',queuePosition:null}),/number 2/);});
test('C2 missing controls disable Continue and takeover',()=>{const html=view({state:'paused',availableControls:[]});assert.match(html,/disabled[^>]*>Continue/);assert.match(html,/disabled[^>]*>Take over/);});
test('C2 private page never renders public Continue even on turn end',()=>{const html=view({state:'turn_ended',privatePage:true,availableControls:[]});assert.doesNotMatch(html,/>Continue<|>Resume</);});
test('C2 read approval never substitutes previously approved entries',async()=>{const {readReview}=await sessionTools();const r=readReview({revision:2,entries:[{canonical_url:'https://city.example/old'}],candidates:null,expires_at:null},0);assert.deepEqual(r.readUrls,[]);assert.equal(r.readExpired,true);});
test('C2 null deadline disables a nonempty read candidate',async()=>{const {readReview}=await sessionTools();assert.equal(readReview({candidates:[{url:'https://city.example/new',server_deadline:null}],expires_at:null},0).readExpired,true);});
test('C2 exact read candidates retain original earliest expiry',async()=>{const {readReview}=await sessionTools();const r=readReview({candidates:[{url:'https://city.example/new',server_deadline:'2099-01-01T00:00:00Z'},{url:'https://city.example/file',server_deadline:'2020-01-01T00:00:00Z'}],expires_at:'2099-01-01T00:00:00Z'},0);assert.equal(r.readExpired,true);assert.equal(r.readUrls.length,2);});
test('C2 fresh reset blocks old detail and frames until new authoritative generation',async()=>{const {createFrameGate}=await sessionTools();const gate=createFrameGate();gate.observe({revision:1,context_generation:4});assert.equal(gate.ready(),true);gate.reset(4);assert.equal(gate.ready(),false);assert.equal(gate.observe({revision:2,context_generation:4}),false);assert.equal(gate.ready(),false);assert.equal(gate.observe({revision:3,context_generation:5}),true);assert.equal(gate.ready(),true);});
test('C2 reset response generation alone cannot unblock presentation',async()=>{const {createFrameGate}=await sessionTools();const gate=createFrameGate();gate.observe({revision:3,context_generation:4});gate.reset(4,6);assert.equal(gate.ready(),false);assert.equal(gate.observe({revision:4,context_generation:5}),false);assert.equal(gate.observe({revision:5,context_generation:6}),true);});
test('C2 fresh gate rejects a stale revision after replacement',async()=>{const {createFrameGate}=await sessionTools();const gate=createFrameGate();gate.observe({revision:10,context_generation:4});gate.reset(4);assert.equal(gate.observe({revision:9,context_generation:5}),false);assert.equal(gate.ready(),false);});
test('C2 paging follows cursor and pins list revision',async()=>{const {collectBrowserPages}=await apiTools();const calls=[];const all=await collectBrowserPages(async(cursor,revision)=>{calls.push([cursor,revision]);return cursor?{items:[2],revision:7,next_cursor:null}:{items:[1],revision:7,next_cursor:'next'};},'items');assert.deepEqual(all.items,[1,2]);assert.deepEqual(calls,[[undefined,undefined],['next',7]]);});
test('C2 stale second page fails closed without publishing partial rows',async()=>{const {collectBrowserPages}=await apiTools();await assert.rejects(()=>collectBrowserPages(async(cursor)=>cursor?{items:[2],revision:8,next_cursor:null}:{items:[1],revision:7,next_cursor:'next'},'items'),e=>e.code==='BROWSER_REVIEW_STALE');});
test('C2 repeated cursor cannot loop forever',async()=>{const {collectBrowserPages}=await apiTools();await assert.rejects(()=>collectBrowserPages(async()=>({items:[],revision:7,next_cursor:'same'}),'items'),e=>e.code==='BROWSER_REVIEW_STALE');});
test('C2 API uses public_research, confirmed reset, B headers and fresh idempotency per mutation',async()=>{const {browserAPI}=await apiTools();const old=globalThis.fetch,calls=[];globalThis.fetch=async(url,options)=>{calls.push({url,options});return Response.json(url.endsWith('/csrf')?{ok:true,csrf_token:'csrf',expires_at:'2099-01-01T00:00:00Z'}:{ok:true});};try{const id='10000000-0000-4000-8000-000000000001',v={viewer_id:id,device_secret:'d'.repeat(43),owner_review_claim:{claim_id:id}};await browserAPI.create({conversation_id:id,task_kind:'public_research',purpose:'Read public page',origins:[{origin:'https://city.example',role:'document'}],initial_url:'https://city.example/',read_proposal:{v:1,entries:[{url:'https://city.example/',role:'document',source:'person'}]}});await browserAPI.control(id,v,'fresh_browser',1);await browserAPI.control(id,v,'fresh_browser',1);const posts=calls.filter(c=>c.options.method==='POST'),bodies=posts.map(c=>JSON.parse(c.options.body));assert.equal(bodies[0].task_kind,'public_research');assert.equal(bodies[1].confirmed,true);assert.equal(posts[1].options.headers['X-SJC-Browser-Claim'],id);assert.equal(posts[1].options.headers['X-SJC-Browser-Viewer'],id);assert.equal(new Set(bodies.map(b=>b.idempotency_key)).size,3);}finally{globalThis.fetch=old;}});
test('C2 settings consumes plain flags without prefixed-key override',async()=>{const {browserFlags}=await sessionTools();assert.deepEqual(browserFlags({enabled:true,staff_enabled:true,'browser.enabled':false}),{enabled:true,staff_enabled:true});assert.deepEqual(browserFlags(null),{enabled:false,staff_enabled:false});});
test('C2 server handshake error retains exact code rather than stream stale',async()=>{const {browserAPI}=await apiTools();const old=globalThis.fetch;globalThis.fetch=async()=>Response.json({ok:false,code:'BROWSER_AUTH_EXPIRED',message:'BROWSER_AUTH_EXPIRED',retryable:false},{status:401});try{await assert.rejects(()=>browserAPI.events('id',{viewer_id:'id',device_secret:'d'},new AbortController().signal,()=>{}),e=>e.code==='BROWSER_AUTH_EXPIRED');}finally{globalThis.fetch=old;}});
test('C2 planned close waits for server ACK before abort',async()=>{const {closeBrowserStream}=await sessionTools();const order=[];let ack;const closing=closeBrowserStream(()=>new Promise(resolve=>{order.push('request');ack=resolve;}),()=>order.push('abort'));assert.deepEqual(order,['request']);ack();await closing;assert.deepEqual(order,['request','abort']);});
test('C2 planned close failure still aborts and never reports an ACK',async()=>{const {closeBrowserStream}=await sessionTools();let aborted=false;await assert.rejects(()=>closeBrowserStream(async()=>{throw Error('refused');},()=>{aborted=true;}),/refused/);assert.equal(aborted,true);});
test('C2 bounded server reasons replace generic pause, never guessed on absence',async()=>{const {browserProjection}=await sessionTools();for(const state_reason of ['idle_closed','turn_ended','owner_paused','absent','crashed','latched','unknown'])assert.equal(browserProjection({projection_status:'available',state_reason,owner_label:'Alex'}).state,state_reason);assert.equal(browserProjection({projection_status:'unavailable',state_reason:null}).state,undefined);});
test('C2 owner/controller/window projection clears absent fields',async()=>{const {browserProjection}=await sessionTools();assert.deepEqual(browserProjection({projection_status:'unavailable',state_reason:null,window_count:null,watching_owner:false,owner_label:null}),{state:undefined,queuePosition:null,watchingOwner:false,ownerName:undefined,windowCount:undefined,controller:undefined});});
